#include <stdio.h>

#define MAXN 50005

int N;
int head[MAXN], to[2 * MAXN], nxt[2 * MAXN], ecnt;
int dist[MAXN], parent[MAXN], queue[MAXN];
int path[MAXN];
int st_node[MAXN], st_parent[MAXN], st_depth[MAXN];

void add_edge(int u, int v) {
    to[ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt++;
}

int bfs(int start) {
    for (int i = 1; i <= N; i++) dist[i] = -1;

    int qh = 0, qt = 0;
    queue[qt++] = start;
    dist[start] = 0;
    parent[start] = -1;

    int far = start;

    while (qh < qt) {
        int u = queue[qh++];
        if (dist[u] > dist[far]) far = u;

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                queue[qt++] = v;
            }
        }
    }

    return far;
}

int count_at_depth(int start, int forbid, int target) {
    int top = 0;
    st_node[top] = start;
    st_parent[top] = forbid;
    st_depth[top] = 0;
    top++;

    int cnt = 0;

    while (top > 0) {
        top--;
        int u = st_node[top];
        int p = st_parent[top];
        int d = st_depth[top];

        if (d == target) {
            cnt++;
            continue;
        }

        if (d < target) {
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                if (v == p) continue;

                st_node[top] = v;
                st_parent[top] = u;
                st_depth[top] = d + 1;
                top++;
            }
        }
    }

    return cnt;
}

int main() {
    scanf("%d", &N);

    for (int i = 1; i <= N; i++) head[i] = -1;
    ecnt = 0;

    for (int i = 0; i < N - 1; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        add_edge(x, y);
        add_edge(y, x);
    }

    int A = bfs(1);
    int B = bfs(A);
    int D = dist[B];

    int idx = D;
    int cur = B;

    while (1) {
        path[idx--] = cur;
        if (cur == A) break;
        cur = parent[cur];
    }

    long long ans;

    if (D % 2 == 0) {
        int c = path[D / 2];
        int r = D / 2;

        long long S = 0, sumSq = 0;

        for (int e = head[c]; e != -1; e = nxt[e]) {
            int v = to[e];
            int cnt = count_at_depth(v, c, r - 1);
            S += cnt;
            sumSq += (long long)cnt * cnt;
        }

        ans = (S * S - sumSq) / 2;
    } else {
        int c1 = path[D / 2];
        int c2 = path[D / 2 + 1];
        int r = D / 2;

        long long cnt1 = count_at_depth(c1, c2, r);
        long long cnt2 = count_at_depth(c2, c1, r);

        ans = cnt1 * cnt2;
    }

    printf("%d\n%lld\n", D + 1, ans);

    return 0;
}
